": ""input"", ""label"": ""Peso Retenido (g)"", ""input_config"": {""name"": ""retenido""}}, {""key"": ""porc_retenido"", ""type"": ""calculated"", ""label"": ""% Ret."", ""result_config"": {""key"": ""porcRet"", ""group"": ""granulometria""}}, {""key"": ""porc_acum"", ""type"": ""calculated"", ""label"": ""% Acum."", ""result_config"": {""key"": ""acum"", ""group"": ""granulometria""}}, {""key"": ""porc_pasa"", ""type"": ""calculated"", ""label"": ""% Pasa"", ""result_config"": {""key"": ""pasa"", ""group"": ""granulometria""}}]}}, ""general_fields"": {""title"": ""Datos Generales"", ""fields"": [{""key"": ""peso_total"", ""type"": ""number"", ""label"": ""Peso Total (g)""}, {""key"": ""peso_fraccion_fina"", ""type"": ""number"", ""label"": ""Peso Fracción Fina (g)""}, {""key"": ""gradacion"", ""type"": ""text"", ""label"": ""Gradación""}], ""layout"": {""width"": ""100%""}}}"
